import { useMemo, useState } from 'react';
import { useT } from '@/i18n';
import { evaluateL4Card, type L4Card } from '@/core/acceptance/l4';
import { L4_TOP30 } from '@/core/acceptance/top30';
import evidenceJson from '../../../../../bench/l4-evidence.json';

type Evidence = Parameters<typeof evaluateL4Card>[0];

const EVIDENCE = new Map(
  (evidenceJson as Evidence[]).map((e) => [e.pluginId, e]),
);

/** Browser view of the 30 L4 cards generated by `npm run l4:report`. */
export default function L4Page() {
  const t = useT();
  const [filter, setFilter] = useState<'all' | 'PASS' | 'FAIL'>('all');
  const cards = useMemo<L4Card[]>(
    () =>
      L4_TOP30.map((p) =>
        evaluateL4Card(EVIDENCE.get(p.pluginId) ?? { ...p }),
      ),
    [],
  );
  const shown = cards.filter((c) => filter === 'all' || c.status === filter);
  const pass = cards.filter((c) => c.status === 'PASS').length;

  return (
    <div className="l4-page">
      <h1>{t('l4.title')}</h1>
      <p className="l4-summary">{t('l4.subtitle')}</p>
      <div>
        <div className="l4-summary">
          {t('l4.summary', { total: cards.length, pass, fail: cards.length - pass })}
        </div>
        <div className="l4-filters">
          {(['all', 'PASS', 'FAIL'] as const).map((value) => (
            <button
              key={value}
              type="button"
              className={`btn btn-sm${filter === value ? ' btn-primary' : ''}`}
              onClick={() => setFilter(value)}
            >
              {value}
            </button>
          ))}
        </div>
        {shown.map((card) => (
          <details key={card.pluginId} className="l4-card">
            <summary>
              <span className={card.status === 'PASS' ? 'l4-pass' : 'l4-fail'}>{card.status}</span>
              {' '}{card.pluginId} <span className="l4-discipline">· {card.discipline}</span>
            </summary>
            <div className="l4-body">
              <p>{t('l4.default')}: {JSON.stringify(card.evidence.defaultMetrics ?? {})}</p>
              <p>{t('l4.extreme')}: {JSON.stringify(card.evidence.extremeParams ?? {})}</p>
              <p>{t('l4.export')}: {JSON.stringify(card.evidence.export ?? {})}</p>
              <p>{t('l4.refresh')}: {JSON.stringify(card.evidence.refresh ?? {})}</p>
              <p>{t('l4.independent')}: {card.evidence.independent?.detail ?? '—'}</p>
              <p>{t('l4.limitations')}: {card.evidence.limitations?.join('; ') ?? '—'}</p>
              {card.reasons.map((reason) => (
                <p key={reason} className="l4-fail">{t('l4.reason', { reason })}</p>
              ))}
            </div>
          </details>
        ))}
      </div>
    </div>
  );
}
